#' Enhanced channel mapping function
#' 
#' Extends the existing channel mapping to include all channel types
#' 
#' @param gs GatingSet object
#' @return data.frame with Marker, Channel, and Channel_Type columns
create_channel_map_enhanced <- function(gs) {
  gh <- gs[[1]]
  fr <- gh_pop_get_data(gh)
  
  markers <- markernames(fr)
  channels <- names(markers)
  
  # Extract channel types
  channel_types <- ifelse(grepl("-A$", channels), "Area",
                   ifelse(grepl("-H$", channels), "Height",
                   ifelse(grepl("-W$", channels), "Width", "Other")))
  
  # Extract marker names more carefully
  channel_map <- data.frame(
    Marker_Full = markers,
    Channel = channels,
    Channel_Type = channel_types,
    stringsAsFactors = FALSE
  ) %>%
    mutate(
      # Extract just the marker name (before the first colon)
      Marker = trimws(gsub(" :.*", "", Marker_Full))
    )
  
  return(channel_map)
}

#' Wrapper function for gate_mindensity
#' 
#' Applies 1D minimum density gating
#' 
#' @param gs GatingSet object
#' @param parent_pop Parent population path
#' @param target_marker Target marker name
#' @param channel_map Channel mapping data frame
#' @param plot_type Type of plot ("1d" or "2d")
#' @param ssc_channel SSC channel for 2D plots
#' @param ... Additional parameters for gate_mindensity
#' @return List with results and plots
apply_gate_mindensity <- function(gs, parent_pop, target_marker, 
                                  channel_map, plot_type = "1d",
                                  ssc_channel = "SSC-A", ...) {
  # browser()
  # Convert marker to channel
  target_channel <- channel_map$Channel[channel_map$Marker == target_marker & 
                                         channel_map$Channel_Type == "Area"]
  
  if (length(target_channel) == 0) {
    stop("Target marker '", target_marker, "' not found in channel map")
  }
  
  target_channel <- target_channel[1]
  
  results <- list()
  plots <- list()
  
  # Apply to all samples
  for (i in seq_along(gs)) {
    sample_name <- sampleNames(gs)[i]
    gh <- gs[[i]]
    
    # Get parent population data
    parent_data <- gh_pop_get_data(gh, parent_pop)
    
    if (plot_type == "1d") {
      # 1D gating
      gate_result <- tryCatch({
        gate_mindensity(parent_data, channel = target_channel, ...)
      }, error = function(e) {
        warning("gate_mindensity failed for sample ", sample_name, ": ", e$message)
        return(NULL)
      })
      
      results[[sample_name]] <- gate_result
      
      # Create 1D histogram plot
      if (!is.null(gate_result)) {
        # Use cyto_plot for 1D histogram
        p <- cyto_plot(parent_data,
                      channels = target_channel,
                      type = "histogram",
                      main = paste("Sample:", sample_name, "- mindensity"))
        # Add vertical line for gate result
        abline(v = gate_result@min, col = "red", lty = "dashed", lwd = 1)
        
        plots[[sample_name]] <- p
      }
    } else if (plot_type == "2d") {
      # 2D gating with SSC-A
      gate_result <- tryCatch({
        gate_mindensity(parent_data, channel = c(target_channel, ssc_channel), ...)
      }, error = function(e) {
        warning("gate_mindensity failed for sample ", sample_name, ": ", e$message)
        return(NULL)
      })
      
      results[[sample_name]] <- gate_result
      
      # Create 2D density plot
      if (!is.null(gate_result)) {
        # Extract gate boundaries for plotting
        if (inherits(gate_result, "rectangleGate")) {
          # For rectangle gates, create a data frame with the four corners
          x_min <- gate_result@min[target_channel]
          x_max <- gate_result@max[target_channel]
          y_min <- gate_result@min[ssc_channel]
          y_max <- gate_result@max[ssc_channel]
          
          gate_boundaries <- data.frame(
            x = c(x_min, x_max, x_max, x_min, x_min),
            y = c(y_min, y_min, y_max, y_max, y_min)
          )
        } else {
          # For other gate types, try to use the boundaries slot
          gate_boundaries <- as.data.frame(gate_result@boundaries)
          names(gate_boundaries) <- c(target_channel, ssc_channel)
        }
        
        # Use cyto_plot for 2D density plot
        p <- cyto_plot(parent_data,
                      channels = c(target_channel, ssc_channel),
                      type = "density",
                      main = paste("Sample:", sample_name, "- mindensity (2D)"))
        # Add gate boundary if available
        if (!is.null(gate_boundaries)) {
          lines(gate_boundaries$x, gate_boundaries$y, col = "red", lwd = 2)
        }
        
        plots[[sample_name]] <- p
      }
    }
  }
  
  return(list(results = results, plots = plots))
}

