#' Create comparison grid of all gating methods
#' 
#' @param method_plots List of plots from different gating methods
#' @param output_file File path to save the grid plot
#' @return Grid plot object
create_comparison_grid <- function(method_plots, output_file = NULL) {
  # Combine all plots into a grid
  # This assumes method_plots is a list with named elements for each method
  # and each element contains plots for different samples
  
  # For simplicity, we'll create a grid for the first sample
  sample_name <- names(method_plots[[1]])[1]
  
  plots_list <- lapply(method_plots, function(x) x[[sample_name]])
  
  # Remove any NULL plots
  plots_list <- plots_list[!sapply(plots_list, is.null)]
  
  # Create grid
  grid_plot <- do.call(grid.arrange, c(plots_list, ncol = 2))
  
  if (!is.null(output_file)) {
    ggsave(output_file, grid_plot, width = 12, height = 8)
  }
  
  return(grid_plot)
}

#' Generate statistical summary for gating results
#' 
#' @param gs GatingSet object
#' @param parent_pop Parent population path
#' @param method_results List of results from different gating methods
#' @return Data frame with summary statistics
generate_summary_stats <- function(gs, parent_pop, method_results) {
  summary_df <- data.frame(
    Sample = character(),
    Method = character(),
    Parent_Count = numeric(),
    Gated_Count = numeric(),
    Percentage = numeric(),
    stringsAsFactors = FALSE
  )
  
  sample_names <- sampleNames(gs)
  
  for (method_name in names(method_results)) {
    method_res <- method_results[[method_name]]
    
    for (sample_name in sample_names) {
      # Get parent population count
      parent_count <- gh_pop_get_count(gs[[which(sample_names == sample_name)]], parent_pop)
      
      # Get gated count (this would depend on how the gate is applied to the GatingSet)
      # For now, we'll just put placeholder values
      gated_count <- NA
      percentage <- NA
      
      # Add to summary
      summary_df <- rbind(summary_df, data.frame(
        Sample = sample_name,
        Method = method_name,
        Parent_Count = parent_count,
        Gated_Count = gated_count,
        Percentage = percentage,
        stringsAsFactors = FALSE
      ))
    }
  }
  
  return(summary_df)
}

#' Main function to compare gating methods
#' 
#' @param gs GatingSet object
#' @param parent_pop Parent population path
#' @param target_marker Target marker name
#' @param methods Vector of method names to compare
#' @param plot_types Vector of plot types ("1d", "2d")
#' @param output_dir Directory to save results
#' @param ... Additional parameters passed to gating methods
#' @return List with results, plots, and summary
compare_gating_methods <- function(gs, parent_pop, target_marker, 
                                    methods = c("mindensity", "flowclust_1d", "flowclust_2d", 
                                               "tailgate", "quantile", "deGate"),
                                    plot_types = c("1d", "2d"),
                                    output_dir = "results/gating_comparison",
                                    ...) {
  
  # Create output directory
  dir.create(output_dir, showWarnings = FALSE, recursive = TRUE)
  dir.create(file.path(output_dir, "plots"), showWarnings = FALSE, recursive = TRUE)
  dir.create(file.path(output_dir, "data"), showWarnings = FALSE, recursive = TRUE)
  
  # Create enhanced channel map
  channel_map <- create_channel_map_enhanced(gs)
  
  # Store results and plots
  all_results <- list()
  all_plots <- list()
  
  # Apply each method
  for (method in methods) {
    cat("Applying", method, "...\n")
    
    # Determine which function to call
    gating_func <- switch(method,
      "mindensity" = apply_gate_mindensity,
      "flowclust_1d" = apply_gate_flowclust_1d,
      "flowclust_2d" = apply_gate_flowclust_2d,
      "tailgate" = apply_gate_tailgate,
      "quantile" = apply_gate_quantile,
      "deGate" = apply_deGate,
      stop("Unknown method: ", method)
    )
    
    # Apply for each plot type
    method_results <- list()
    method_plots <- list()
    
    for (plot_type in plot_types) {
      # Call the appropriate function
      if (method %in% c("mindensity", "flowclust_1d", "tailgate", "quantile", "deGate")) {
        res <- gating_func(gs, parent_pop, target_marker, channel_map, 
                           plot_type = plot_type, ...)
        method_results[[plot_type]] <- res$results
        method_plots[[plot_type]] <- res$plots
      } else if (method == "flowclust_2d") {
        # flowclust_2d is always 2D
        if (plot_type == "2d") {
          res <- gating_func(gs, parent_pop, target_marker, channel_map, ...)
          method_results[[plot_type]] <- res$results
          method_plots[[plot_type]] <- res$plots
        }
      }
    }
    
    all_results[[method]] <- method_results
    all_plots[[method]] <- method_plots
  }
  
  # Generate summary statistics
  summary_stats <- generate_summary_stats(gs, parent_pop, all_results)
  
  # Create comparison grids
  comparison_grids <- list()
  for (plot_type in plot_types) {
    # Collect plots for this plot type
    plots_for_type <- list()
    for (method in methods) {
      if (!is.null(all_plots[[method]][[plot_type]])) {
        plots_for_type[[method]] <- all_plots[[method]][[plot_type]]
      }
    }
    
    if (length(plots_for_type) > 0) {
      grid_file <- file.path(output_dir, "plots", 
                            paste0("comparison_grid_", plot_type, ".png"))
      comparison_grids[[plot_type]] <- create_comparison_grid(plots_for_type, grid_file)
    }
  }
  
  # Save results
  saveRDS(list(
    results = all_results,
    plots = all_plots,
    summary = summary_stats,
    grids = comparison_grids
  ), file.path(output_dir, "data", "gating_comparison_results.rds"))
  
  # Save summary statistics
  write.csv(summary_stats, file.path(output_dir, "data", "summary_statistics.csv"), 
            row.names = FALSE)
  
  # Return results
  return(list(
    results = all_results,
    plots = all_plots,
    summary = summary_stats,
    grids = comparison_grids,
    output_dir = output_dir
  ))
}

